import { greet, shout } from "../src/greet.js";

const failures = [];
if (greet("Ada") !== "Hello, Ada!") failures.push("greet regressed");
if (shout("ship") !== "SHIP!") failures.push("shout missing or wrong");
if (failures.length > 0) {
  console.error(failures.join("; "));
  process.exitCode = 1;
} else {
  console.log("ok");
}

solution.content:
export function greet(name) {
  return `Hello, ${name}!`;
}

export function shout(message) {
  return `${message.toUpperCase()}!`;
}
